function activateSlow(){if(!learned.has('time1')){toast('LEARN STILL THE HOUR IN THE SIGIL TREE');return}const cost=learned.has('time3')?22:28;if(player.charge<cost||elapsed<slowUntil)return;player.charge-=cost;slowUntil=elapsed+(learned.has('time7')?9:learned.has('time2')?7.5:5.5);toast('TIME VEIL — THE WORLD HOLDS ITS BREATH');updateHUD()}
 function activateFold(){if(!learned.has('space1')){toast('LEARN FOLD THE WAY IN THE SIGIL TREE');return}const cost=learned.has('space7')?20:learned.has('space2')?25:35;if(player.charge<cost||elapsed<foldUntil){if(player.charge<cost)toast('INSUFFICIENT AETHER');return}player.charge-=cost;foldUntil=elapsed+1.6;let best=null,bd=99;for(const e of enemies)if(e.alive){const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<bd&&d>1.3&&canSee(player.x,player.y,e.x,e.y)){best=e;bd=d}}if(best){const dx=best.x-player.x,dy=best.y-player.y,d=Math.hypot(dx,dy),tx=best.x-dx/d*1.35,ty=best.y-dy/d*1.35;if(!cell(tx,ty)){player.x=tx;player.y=ty;magicUntil=elapsed+.8;toast('SPACE FOLD — REALITY BENDS')}else toast('SPACE FOLD — ANCHOR OBSCURED')}else toast('SPACE FOLD — NO VISIBLE ANCHOR');updateHUD()}
 function activateFlicker(){if(!learned.has('space3')){toast('FLICKER IS SEALED — LEARN ITS SIGIL');return}const cost=learned.has('space7')?20:30;if(player.charge<cost){toast('INSUFFICIENT AETHER');return}if(elapsed<flickerUntil){toast('FLICKER REFORMING');return}let range=learned.has('space4')?6.2:4.5,tx=player.x,ty=player.y;for(let d=range;d>=1.15;d-=.12){const x=player.x+Math.cos(player.a)*d,y=player.y+Math.sin(player.a)*d;if(!cell(x,y)&&!cell(x+.18,y)&&!cell(x-.18,y)&&!cell(x,y+.18)&&!cell(x,y-.18)&&!enemies.some(e=>e.alive&&Math.hypot(e.x-x,e.y-y)<.65)){tx=x;ty=y;break}}if(tx===player.x&&ty===player.y){toast('FLICKER FALTERS — NO CLEAR SPACE');return}player.charge-=cost;player.x=tx;player.y=ty;flickerUntil=elapsed-(learned.has('space6')?1:0)+4;magicUntil=elapsed+1.1;if(learned.has('space5'))player.hp=Math.min(100,player.hp+8);toast('FLICKER — SPACE COLLAPSED');updateHUD()}

