function update(dt){elapsed+=dt;shootCD=Math.max(0,shootCD-dt);if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){let n=Math.min(12-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;updateHUD()}}if(elapsed>slowUntil&&player.charge<100)player.charge=Math.min(100,player.charge+dt*5.2);if(player.charge<=0)slowUntil=0;
 let speed=2.4*(keys.shift?1.55:1)*(elapsed<slowUntil?1.25:1),move=0,strafe=0;if(keys.w||keys.arrowup)move++;if(keys.s||keys.arrowdown)move--;if(keys.a)strafe--;if(keys.d)strafe++;if(keys.left||keys.arrowleft)player.a-=dt*1.8;if(keys.right||keys.arrowright)player.a+=dt*1.8;if(move||strafe){let vx=(Math.cos(player.a)*move-Math.sin(player.a)*strafe)*speed*dt,vy=(Math.sin(player.a)*move+Math.cos(player.a)*strafe)*speed*dt;if(!cell(player.x+vx+.16,player.y))player.x+=vx;if(!cell(player.x,player.y+vy+.16))player.y+=vy;walkBob+=dt*9;useLoot()}
 const slow=elapsed<slowUntil?.18:1;for(const e of enemies)if(e.alive){e.attack-=dt*slow;e.phase+=dt*slow;let d=Math.hypot(player.x-e.x,player.y-e.y);if(d>1.15&&canSee(e.x,e.y,player.x,player.y)){let vx=(player.x-e.x)/d*e.speed*dt*slow,vy=(player.y-e.y)/d*e.speed*dt*slow;if(!cell(e.x+vx,e.y))e.x+=vx;if(!cell(e.x,e.y+vy))e.y+=vy}else if(d<1.6&&e.attack<=0){e.attack=1.05;player.hp-=e.elite?12:7;damagePulse=1;if(player.hp<=0){player.hp=0;updateHUD();toast('SIGNAL LOST — REINITIALIZING');setTimeout(()=>{player.hp=100;player.x=2.5;player.y=2.5;player.ammo=12;spawnStage();toast('TIMELINE REBOUND')},900)}}}
 for(let i=loot.length-1;i>=0;i--){loot[i].life-=dt;if(loot[i].life<=0)loot.splice(i,1)}if(enemies.every(e=>!e.alive)&&running)nextStep();updateHUD()}
function loop(now){if(!running)return;let dt=Math.min(.05,(now-last)/1000||0);last=now;if(!paused){update(dt);render()}requestAnimationFrame(loop)}
