 document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('touchstart',e=>{e.preventDefault();keys[k]=true},{passive:false});b.addEventListener('touchend',()=>keys[k]=false)});document.getElementById('touchFire').addEventListener('touchstart',e=>{e.preventDefault();shoot()});document.getElementById('touchTime').addEventListener('touchstart',e=>{e.preventDefault();activateSlow()});document.getElementById('touchFold').addEventListener('touchstart',e=>{e.preventDefault();activateFold()});
