/* Medieval spellbound art direction */
:root{--ink:#17120c;--panel:rgba(31,24,16,.94);--line:rgba(202,167,105,.42);--mint:#e2c47e;--cyan:#9ec8bc;--gold:#f2d89a;--red:#c86d5f;--muted:#b9a98d}
