.slot{border:1px solid rgba(202,167,105,.45);background:rgba(32,27,17,.88);color:#c7b27e;clip-path:polygon(10% 0,90% 0,100% 10%,100% 90%,90% 100%,10% 100%,0 90%,0 10%)}
