import { chromium } from 'playwright';
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:1280,height:720}});
const errors=[];page.on('pageerror',e=>errors.push(String(e)));
await page.goto('http://localhost:3000',{waitUntil:'networkidle'});
await page.click('#start');
await page.waitForTimeout(300);
console.log('started',await page.locator('#intro').evaluate(e=>e.classList.contains('hidden')),'hostiles',await page.textContent('#hostiles'));
await page.keyboard.press('k');
await page.waitForTimeout(100);
console.log('treeOpen',await page.locator('#treePanel').evaluate(e=>!e.classList.contains('hidden')),'points',await page.textContent('#skillPoints'));
console.log('lockedFlicker',await page.locator('.skillNode').evaluateAll(ns=>ns.find(n=>n.textContent.includes('Flicker'))?.disabled));
await page.keyboard.press('Escape');
await page.waitForTimeout(100);
console.log('treeClosedEsc',await page.locator('#treePanel').evaluate(e=>e.classList.contains('hidden')));
await page.keyboard.press('q');await page.waitForTimeout(100);console.log('timeToast',await page.textContent('#toast'));
await page.keyboard.press('e');await page.waitForTimeout(100);console.log('foldToast',await page.textContent('#toast'));
await page.keyboard.press('f');await page.waitForTimeout(100);console.log('flickerToast',await page.textContent('#toast'));
await page.keyboard.press('k');await page.waitForTimeout(100);
// Learn a legal first-node in each branch using 2 points.
for (const name of ['Still the Hour','Fold the Way','Witchlight']) {
  const node=page.locator('.skillNode').filter({hasText:name});
  console.log('node',name,'disabled',await node.isDisabled());
  if(await node.isEnabled()) await node.click();
}
console.log('pointsAfter',await page.textContent('#skillPoints'),'owned',await page.locator('.skillNode.owned').count());
await page.keyboard.press('Escape');
await page.keyboard.press('q');await page.waitForTimeout(100);console.log('timeCharge',await page.textContent('#charge'),'timeToast',await page.textContent('#toast'));
await page.keyboard.press('e');await page.waitForTimeout(100);console.log('foldCharge',await page.textContent('#charge'),'foldToast',await page.textContent('#toast'));
console.log('errors',errors);
await browser.close();
EOF
